(() => {
const viewport=document.getElementById('viewport'),board=document.getElementById('board'),pointers=new Map();let scale=1,x=0,y=0,start=null,suppressUntil=0;
const now=()=>Date.now();
function apply(smooth=false){const width=board.offsetWidth||window.gameDebug.scene.W*64,height=board.offsetHeight||window.gameDebug.scene.H*64,vw=viewport.clientWidth,vh=viewport.clientHeight;x=width*scale<vw?(vw-width*scale)/2:Math.max(vw-width*scale-30,Math.min(30,x));y=height*scale<vh?(vh-height*scale)/2:Math.max(vh-height*scale-30,Math.min(30,y));board.style.transition=smooth?'transform 260ms cubic-bezier(.2,.7,.2,1)':'none';board.style.transform=`translate3d(${x}px,${y}px,0) scale(${scale})`}
function center(p,smooth=false){x=viewport.clientWidth/2-(p.x+.5)*64*scale;y=viewport.clientHeight/2-(p.y+.5)*64*scale;apply(smooth)}
function zoom(next,cx=viewport.clientWidth/2,cy=viewport.clientHeight/2){const old=scale;scale=Math.max(.3,Math.min(2.2,next));x=cx-(cx-x)*scale/old;y=cy-(cy-y)*scale/old;apply()}
function reset(){scale=Math.max(.5,Math.min(1.1,viewport.clientWidth/(9*64)));center(window.gameDebug.active());}
function fit(){const S=window.gameDebug.scene;scale=Math.min(viewport.clientWidth/(S.W*64),viewport.clientHeight/(S.H*64))*.94;center({x:S.W/2-.5,y:S.H/2-.5},true)}
function captureStart(){const a=[...pointers.values()];start={x,y,scale,points:a.map(p=>({...p})),distance:a.length===2?Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y):0}}
viewport.addEventListener('pointerdown',e=>{if(e.target.closest('.camera-tip'))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});captureStart()});
viewport.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId)||!start)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});const a=[...pointers.values()];if(a.length===2&&start.points.length===2){const rect=viewport.getBoundingClientRect(),cx=(start.points[0].x+start.points[1].x)/2-rect.left,cy=(start.points[0].y+start.points[1].y)/2-rect.top,ratio=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)/Math.max(start.distance,1);scale=Math.max(.3,Math.min(2.2,start.scale*ratio));x=cx-(cx-start.x)*scale/start.scale+((a[0].x+a[1].x)-(start.points[0].x+start.points[1].x))/2;y=cy-(cy-start.y)*scale/start.scale+((a[0].y+a[1].y)-(start.points[0].y+start.points[1].y))/2;suppressUntil=now()+200;apply();e.preventDefault()}else if(a.length===1&&start.points.length===1){const dx=a[0].x-start.points[0].x,dy=a[0].y-start.points[0].y;if(Math.hypot(dx,dy)>5){x=start.x+dx;y=start.y+dy;suppressUntil=now()+200;viewport.setPointerCapture?.(e.pointerId);apply();e.preventDefault()}}});
function release(e){pointers.delete(e.pointerId);if(pointers.size)captureStart();else start=null}viewport.addEventListener('pointerup',release);viewport.addEventListener('pointercancel',release);
viewport.addEventListener('wheel',e=>{e.preventDefault();const r=viewport.getBoundingClientRect();zoom(scale*Math.exp(-e.deltaY*.001),e.clientX-r.left,e.clientY-r.top)},{passive:false});
window.initCamera=()=>{document.getElementById('zoom-in').onclick=()=>zoom(scale*1.2);document.getElementById('zoom-out').onclick=()=>zoom(scale/1.2);document.getElementById('camera-center').onclick=()=>center(window.gameDebug.active(),true);document.getElementById('camera-fit').onclick=fit;new ResizeObserver(()=>apply()).observe(viewport);reset()};
window.camera={center,reset,fit,zoom,allowClick:()=>now()>suppressUntil,follow(p){const px=x+(p.x+.5)*64*scale,py=y+(p.y+.5)*64*scale;if(px<70||px>viewport.clientWidth-70||py<70||py>viewport.clientHeight-70)center(p,true)},get state(){return{x,y,scale}}};
})();
